<?php require 'app.php';need_school(['director']);$sid=school_id();$q=db()->prepare('SELECT * FROM school_settings WHERE school_id=?');$q->execute([$sid]);$s=$q->fetch()?:[];$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{$logo=cloud_upload('logo');if($logo){db()->prepare('UPDATE schools SET logo_url=? WHERE id=?')->execute([$logo,$sid]);}$q=db()->prepare('INSERT INTO school_settings(school_id,academic_label,card_color) VALUES(?,?,?) ON CONFLICT(school_id) DO UPDATE SET academic_label=EXCLUDED.academic_label,card_color=EXCLUDED.card_color');$q->execute([$sid,trim($_POST['academic_label']),$_POST['card_color']]);$msg='School settings updated.';}catch(Throwable $e){$msg=$e->getMessage();}}$q=db()->prepare('SELECT * FROM schools WHERE id=?');$q->execute([$sid]);$school=$q->fetch();ob_start();?><div class="panel"><h2>School profile and ID card settings</h2><p><?=h($msg)?></p><form method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=h(csrf())?>"><label>School name</label><input value="<?=h($school['name'])?>" disabled><label>Academic year label</label><input name="academic_label" value="<?=h($s['academic_label']??'Academic Year')?>"><label>Card theme colour</label><input type="color" name="card_color" value="<?=h($s['card_color']??'#123f72')?>"><label>School logo (PNG/JPG/WEBP)</label><input type="file" name="logo" accept="image/*"><button>Save settings</button></form></div><?php page('School Settings',ob_get_clean());
